package com.example.puller.entity;import javax.persistence.*;import java.util.Date;@Entity @Table(name="outbox_event") public class OutboxEvent{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="aggregate_id")private String aggregateId;@Column(name="event_type")private String eventType;@Lob @Column(columnDefinition="LONGTEXT")private String payload;private String status;@Column(name="retry_count")private int retryCount;@Temporal(TemporalType.TIMESTAMP)@Column(name="created_at")private Date createdAt;@Temporal(TemporalType.TIMESTAMP)@Column(name="locked_at")private Date lockedAt;@Temporal(TemporalType.TIMESTAMP)@Column(name="published_at")private Date publishedAt;public Long getId(){return id;}public String getAggregateId(){return aggregateId;}public String getEventType(){return eventType;}public String getPayload(){return payload;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public int getRetryCount(){return retryCount;}public void setRetryCount(int v){retryCount=v;}public Date getCreatedAt(){return createdAt;}public Date getLockedAt(){return lockedAt;}public void setLockedAt(Date v){lockedAt=v;}public Date getPublishedAt(){return publishedAt;}public void setPublishedAt(Date v){publishedAt=v;}}
